# Generate a graph with 15 vertices and between 28 and 37 edges
edges = []
count = 0
target = 30  # Pick 30 edges, which is between 28 and 37

for u in range(15):
    for v in range(u+1, 15):
        if count < target:
            edges.append((u, v))
            count += 1
        else:
            break
    if count >= target:
        break

print(f"Number of edges: {len(edges)}")
print(f"Edges: {edges}")

# Verify all constraints
assert len(edges) >= 28 and len(edges) <= 37, "Edge count out of range"
for u, v in edges:
    assert 0 <= u < v < 15, f"Invalid edge: ({u}, {v})"

print("All constraints satisfied!")
